/* story-form-10 — Antenna→Volume street handoff */
.rp-stage-prop--av-handoff {
  left: 12%; right: 12%; top: 28%; height: 32%;
  z-index: 8; color: #e8b478;
  animation: rp-av-pulse 2.4s ease-in-out infinite;
}
.rp-av-handoff-svg, .rp-vl-handoff-svg { width: 100%; height: 100%; display: block; }
@keyframes rp-av-pulse {
  0%, 100% { opacity: 0.92; }
  50% { opacity: 1; filter: drop-shadow(0 0 6px rgba(126,184,212,.35)); }
}
.rp-stage-prop--vl-handoff {
  left: 18%; right: 18%; top: 52%; height: 22%;
  z-index: 8; color: #e8c9a0;
}
.rp-handoff-banner {
  position: absolute; left: 50%; bottom: 5.2rem;
  transform: translateX(-50%);
  z-index: 8;
  max-width: min(92%, 22rem);
  padding: 0.45rem 0.7rem;
  background: rgba(14,10,8,.88);
  border: 1px solid rgba(232,180,120,.45);
  border-radius: 10px;
  color: #f2e6d8;
  font-size: 12px;
  line-height: 1.35;
}
.rp-handoff-banner__h { font-weight: 700; margin: 0 0 0.15rem; }
.rp-handoff-banner__cta {
  margin-top: 0.35rem;
  display: inline-block;
  padding: 0.25rem 0.55rem;
  border: 1px solid #e8b478;
  border-radius: 6px;
  background: transparent;
  color: #e8b478;
  font-size: 11px;
}
/* one handoff layer: hide full arc banners while handoff banner up */
body.rp-handoff-av .rp-arc-beat-banner,
body.rp-handoff-vl .rp-arc-beat-banner { display: none; }

