function storyForm10() {
  return state.questPack?.storyForm10 || state.storyForm10 || null;
}

function whenHandoffOk(h) {
  const day = state.save.dayIndex || 1;
  const w = h.when || {};
  if ((w.dayIndexMin || 0) > day) {
    // optional early tease
    const early = w.orEarlyTease;
    if (!early || (early.dayIndexMin || 0) > day) return false;
    if (!flagsMatch(early)) return false;
  } else if (!flagsMatch(w)) return false;
  // form9: don't steal cold Day2 first paint
  if (day === 2 && ["cold_open_mediate","cold_open_instigate","cold_open_stage"].some(storyFlag)) {
    if (!storyFlag("day2_prop_ack") && !storyFlag("hide_day2_spotlight")) return false;
  }
  return true;
}

function streetHandoffHtml(screen) {
  const beats = (storyForm10()?.streetHandoffBeats || [])
    .filter((h) => (h.screens || []).includes(screen))
    .filter(whenHandoffOk)
    .sort((a,b) => (b.priority||0) - (a.priority||0));
  const hit = beats[0];
  if (!hit) { document.body.classList.remove("rp-handoff-av","rp-handoff-vl"); return ""; }
  if (hit.id.includes("antenna_to_volume")) document.body.classList.add("rp-handoff-av");
  if (hit.id.includes("volume_to_ledger")) document.body.classList.add("rp-handoff-vl");
  for (const f of hit.setsFlagsOnShow || []) state.save.storyFlags[f] = true;
  const prop = (state.locale==="tr" && hit.stageProp.htmlTr) ? hit.stageProp.htmlTr : hit.stageProp.html;
  const ban = hit.compactBanner;
  const bubble = hit.npcLine ? hotspotBubbleFor(hit.npcLine) : "";
  return prop + bubble + handoffBannerHtml(ban);
}

